1: (() => {
2:   const SAVE_KEY = 'ecos-destino-save-v1';
3:   const regions = [
4:     {id:'valtherion',name:'Valtherion',city:'Brumafria',title:'Vale de Cinzas',label:'VALE DE CINZAS',tone:'Reino humano · comércio, intrigas e guerras de sucessão.',symbol:'♜',travel:0,desc:'A estrada de pedra desce entre colinas cobertas de névoa. Ao longe, a vila de Brumafria acende suas primeiras lanternas — pequenas brasas contra uma noite que parece observar você.',culture:'Humana, pragmática e dividida entre juramentos feudais.',religion:'A Chama Perene, que promete manter os mortos em repouso.',conflict:'A Casa Veyne disputa o trono com os barões do norte.',creatures:'Corvos-de-ferrugem, cães selvagens e espectros de estrada.',secret:'Nas fundações da velha capela, sinos tocam quando ninguém os puxa.',faction:'Companhia do Veado Negro',economy:'Ferro, lã e vinho escuro',event:'Um cobrador real desapareceu na estrada, levando os impostos da colheita.'},
5:     {id:'elarion',name:'Elarion',city:'Lúmenfolha',title:'Bosque dos Sussurros',label:'ELARION',tone:'Florestas antigas · elfos, espíritos e criaturas mágicas.',symbol:'♧',travel:6,desc:'Árvores ancestrais erguem raízes como muralhas. Luzes azuladas flutuam entre os galhos, e cada passo parece despertar uma lembrança que não é sua.',culture:'Clãs élficos guardam trilhas e nomes que antecedem a Ruptura.',religion:'O Círculo das Estações, reverência aos espíritos da mata.',conflict:'Os guardiões discutem se devem expulsar os lenhadores humanos.',creatures:'Cervos de cristal, dríades e lobos com olhos de âmbar.',secret:'Uma árvore oca cresce para baixo, em direção a um céu subterrâneo.',faction:'Círculo da Folha Velada',economy:'Ervas raras, âmbar e madeira viva',event:'A seiva de uma árvore sagrada escureceu durante a noite.'},
6:     {id:'skarheim',name:'Skarheim',city:'Fjallgard',title:'Marchas de Gelo',label:'SKARHEIM',tone:'Terras congeladas · guerreiros, gigantes e fortalezas.',symbol:'❄',travel:9,desc:'O vento varre a neve em lâminas finas. Contra o horizonte, fortalezas de pedra negra resistem ao inverno — e algo colossal se move entre os picos.',culture:'Clãs juramentados medem honra pelo que se protege, não pelo que se conquista.',religion:'Os Ancestrais sob a Montanha, cujo silêncio é um aviso.',conflict:'Dois jarls culpam um ao outro pelo despertar dos gigantes.',creatures:'Trolls de gelo, ursos espectrais e gigantes errantes.',secret:'Sob o gelo mais antigo há uma porta que respira calor.',faction:'Juramento do Machado Branco',economy:'Ferro frio, peles e sal',event:'Uma caravana chegou sem condutores; suas pegadas terminam no meio da neve.'},
7:     {id:'mordrath',name:'Mordrath',city:'Véspera',title:'Terras da Vigília',label:'MORDRATH',tone:'Território amaldiçoado · necromantes, mortos-vivos e magia proibida.',symbol:'☠',travel:12,desc:'A névoa aqui não se dissipa ao amanhecer. Torres partidas inclinam-se sobre charcos negros, e as sombras projetadas pelas ruínas apontam para o sol.',culture:'Sobreviventes mantêm pactos de silêncio e portas sem espelhos.',religion:'Cultos locais negociam com os mortos; a Igreja chama isso de heresia.',conflict:'A Ordem do Véu caça um necromante que talvez esteja protegendo a vila.',creatures:'Carniçais, corvos sem rosto e ecos famintos.',secret:'Os mortos de Véspera sonham a mesma memória, embora tenham vivido séculos diferentes.',faction:'Ordem do Véu Cinzento',economy:'Relíquias, sal negro e serviços clandestinos',event:'Alguém deixou uma vela acesa em cada túmulo, mas a cera queima para cima.'},
8:     {id:'thalassar',name:'Thalassar',city:'Porto Salmoura',title:'Costa das Marés Mortas',label:'THALASSAR',tone:'Cidades portuárias · piratas, comércio e monstros marinhos.',symbol:'⚓',travel:8,desc:'O mar bate contra o cais com uma cadência quase humana. Velas de toda bandeira disputam espaço no porto, enquanto algo enorme risca a superfície além dos recifes.',culture:'Capitães elegem conselhos; lealdade é valiosa, mas nunca gratuita.',religion:'A Mãe das Marés recebe moedas e nomes antes de cada travessia.',conflict:'A guilda mercante acusa piratas de afundar navios sem saqueá-los.',creatures:'Enguias-lanterna, harpias costeiras e leviatãs adormecidos.',secret:'Uma ilha aparece apenas em cartas náuticas desenhadas por quem está morto.',faction:'Liga das Sete Velas',economy:'Sal, especiarias, pesca e mapas',event:'Um navio vazio retornou ao porto com água do mar pingando de dentro para fora.'}
9:   ];
10:   const npcTemplates = [
11:     {id:'mara',name:'Mara Vell',age:34,role:'estalajadeira',initial:'M',look:'Cabelos grisalhos presos num lenço vermelho; mãos marcadas pelo trabalho.',personality:'Prática, observadora e ferozmente leal a quem paga suas dívidas.',history:'Herdou a estalagem do irmão, desaparecido na estrada há três invernos.',goals:'Manter a estalagem aberta e descobrir o que houve com o irmão.',fear:'Que a vila seja abandonada antes do inverno.',desire:'Uma resposta honesta, mesmo que doa.',knowledge:'Conhece rumores da estrada, preços e rostos que passam pela vila.',relation:'Neutra; avalia você com cautela.',memory:[]},
12:     {id:'cael',name:'Irmão Cael',age:51,role:'guardião da capela',initial:'C',look:'Um sacerdote magro, com uma cicatriz atravessando a sobrancelha e um rosário de ferro.',personality:'Gentil em público, inquieto quando ouve sinos.',history:'Sobreviveu ao incêndio da capela antiga; nunca fala de quem o tirou dos escombros.',goals:'Impedir que a cripta seja aberta.',fear:'Que os mortos recordem seu nome.',desire:'Descanso para os que não conseguem morrer.',knowledge:'Conhece liturgias antigas e a história oficial da Ruptura.',relation:'Respeitoso, mas desconfiado.',memory:[]},
13:     {id:'tovin',name:'Tovin Rusk',age:28,role:'batedor',initial:'T',look:'Um jovem de olhos atentos, capa de couro gasta e uma luva sem dedos.',personality:'Irônico, impulsivo e mais corajoso do que admite.',history:'Desertou de uma patrulha baronial após receber ordens para queimar uma aldeia.',goals:'Encontrar trabalho que não exija fechar os olhos.',fear:'Voltar a obedecer a ordens cruéis.',desire:'Ser lembrado por algo que escolheu fazer.',knowledge:'Trilhas, patrulhas e sinais de criaturas na mata.',relation:'Curioso; ainda não decidiu se confia em você.',memory:[]}
14:   ];
15:   const questSeeds = [
16:     {id:'taxes',title:'O coletor que não voltou',giver:'Mara Vell',kind:'RUMOR · BRUMAFRIA',desc:'Um cobrador real sumiu na estrada com os impostos da colheita. Mara ouviu cavalos depois da meia-noite.',state:'Disponível',progress:0},
17:     {id:'bells',title:'Sinos sob a terra',giver:'Irmão Cael',kind:'MISTÉRIO · CAPELA VELHA',desc:'O sino da capela abandonada tocou três vezes, embora sua torre tenha desabado há décadas.',state:'Disponível',progress:0}
18:   ];
19:   const initial = () => ({name:'Viajante',className:'Andarilho',level:1,xp:0,hp:28,maxHp:28,stamina:18,maxStamina:18,gold:24,might:12,wit:13,rep:'Desconhecido',region:'valtherion',day:1,time:17*60+40,turn:0,items:['Espada curta','Manto de viagem','Pederneira','3 rações','Frasco de tônico','Mapa incompleto'],story:[],quests:JSON.parse(JSON.stringify(questSeeds)),npcs:{},events:[],secrets:[],flags:{},memory:'Você chegou a Brumafria no fim de tarde. A origem da Ruptura permanece desconhecida.',sound:false});
20:   let state;
21:   try { state = JSON.parse(localStorage.getItem(SAVE_KEY)) || initial(); } catch { state = initial(); }
22:   if (!state.npcs || !Object.keys(state.npcs).length) state.npcs = Object.fromEntries(npcTemplates.map(n=>[n.id,{...n,memory:[]} ]));
23:   const $ = id => document.getElementById(id);
24:   const esc = s => String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
25:   const save = () => { try { localStorage.setItem(SAVE_KEY,JSON.stringify(state)); } catch(e) { console.warn('Não foi possível salvar',e); } };
26:   let toastTimer;
27:   function toast(msg){const el=$('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2400);}
28:   function currentRegion(){return regions.find(r=>r.id===state.region)||regions[0];}
29:   function timeText(){let h=Math.floor(state.time/60)%24,m=state.time%60;return `${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}`;}
30:   function addEntry(text,opts={}){state.story.push({text,time:timeText(),day:state.day,system:!!opts.system,result:opts.result||''});if(state.story.length>80)state.story=state.story.slice(-80);}
31:   function updateMemory(){const recent=state.story.slice(-8).map(x=>x.text.replace(/<[^>]*>/g,'')).join(' ');state.memory=`${state.name}, ${state.className} nível ${state.level}, está em ${currentRegion().city}, ${currentRegion().name}. Ouro: ${state.gold}; relações e fios: ${state.quests.filter(q=>q.state==='Em andamento').map(q=>q.title).join(', ')||'nenhum ativo'}. Acontecimentos recentes: ${recent.slice(-500)}`;}
32:   function render(){
33:     const r=currentRegion(); $('characterName').textContent=state.name;$('characterClass').textContent=`${state.className} · Nv. ${state.level}`;$('avatarInitial').textContent=state.name[0].toUpperCase();$('topAvatar').textContent=state.name[0].toUpperCase();
34:     $('topLocation').textContent=r.label;$('locationTitle').innerHTML=esc(r.title).replace(' ', ' <br><em>').replace(/$/, '</em>');
35:     // Keep a deliberate two-line title without changing region copy.
36:     const titleParts=r.title.split(' ');$('locationTitle').innerHTML=`${esc(titleParts.slice(0,Math.max(1,Math.ceil(titleParts.length/2))).join(' '))}<br><em>${esc(titleParts.slice(Math.max(1,Math.ceil(titleParts.length/2))).join(' ')||'Aetherion.')}</em>`;
37:     $('locationDescription').textContent=r.desc;$('hero').querySelector('.eyebrow').innerHTML=`<span class="eyebrow-line"></span> ${esc(r.label)} <span class="tag">${esc(r.name.toUpperCase())}</span>`;
38:     $('hpText').textContent=`${state.hp} / ${state.maxHp}`;$('hpBar').style.width=`${100*state.hp/state.maxHp}%`;$('staminaText').textContent=`${state.stamina} / ${state.maxStamina}`;$('staminaBar').style.width=`${100*state.stamina/state.maxStamina}%`;$('goldValue').textContent=state.gold;$('repValue').textContent=state.rep;$('mightValue').textContent=state.might;$('witValue').textContent=state.wit;$('itemCount').textContent=`${state.items.length} ${state.items.length===1?'item':'itens'}`;
39:     $('xpLabel').textContent=`${state.xp} / ${state.level*100} XP`;$('xpBar').style.width=`${Math.min(100,100*state.xp/(state.level*100))}%`;$('turnLabel').textContent=`DIA ${String(state.day).padStart(2,'0')} · ${timeText()}`;
40:     $('storyFeed').innerHTML=state.story.slice(-8).map(e=>`<article class="story-entry ${e.system?'system-entry':''}"><div class="entry-time">DIA ${String(e.day).padStart(2,'0')} · ${e.time}${e.system?' · PRESSÁGIO':''}</div><p>${e.text}</p>${e.result?`<div class="entry-result">${e.result}</div>`:''}</article>`).join('');
41:     renderQuests();renderPeople();renderJournal();renderCodex();$('questCount').textContent=state.quests.filter(q=>q.state==='Em andamento'||q.state==='Disponível').length;save();
42:   }
43:   function renderQuests(){const active=state.quests.filter(q=>q.state==='Em andamento'||q.state==='Disponível').slice(0,3);$('activeQuests').innerHTML=active.length?active.map(q=>`<div class="quest-mini"><i class="quest-pin"></i><div><span class="quest-kind">${esc(q.kind)} · ${q.state==='Em andamento'?'EM CURSO':'RUMOR'}</span><b>${esc(q.title)}</b><small>${esc(q.desc)}</small></div></div>`).join(''):'<div class="quest-mini"><i class="quest-pin"></i><div><b>Nenhum fio em aberto</b><small>O mundo espera pela sua próxima escolha.</small></div></div>';
44:     $('journalContent').innerHTML=`<div class="journal-grid">${state.quests.map(q=>`<article class="journal-card"><span class="eyebrow">${esc(q.kind)}</span><h3>${esc(q.title)}</h3><div class="journal-state">${esc(q.state.toUpperCase())}${q.giver?` · ${esc(q.giver)}`:''}</div><p>${esc(q.desc)}</p>${q.note?`<p><b>Registro:</b> ${esc(q.note)}</p>`:''}${q.state==='Disponível'?`<button class="text-link quest-start" data-id="${esc(q.id)}">Investigar →</button>`:''}</article>`).join('')}<article class="journal-card"><span class="eyebrow">MEMÓRIA NARRATIVA</span><h3>O que não se perde</h3><p>${esc(state.memory)}</p><div class="journal-state">${state.events.length} ACONTECIMENTOS REGISTRADOS</div></article></div>`;
45:     document.querySelectorAll('.quest-start').forEach(b=>b.onclick=()=>startQuest(b.dataset.id));
46:   }
47:   function renderPeople(){const list=Object.values(state.npcs).filter(n=>n.met);$('recentPeople').innerHTML=list.length?list.slice(-3).reverse().map(n=>`<div class="person-row"><div class="person-avatar">${esc(n.initial)}</div><div class="person-info"><b>${esc(n.name)}</b><small>${esc(n.role)} · ${esc(n.relation.split(';')[0])}</small></div><span class="person-attitude">${n.trust>2?'✦':n.trust<0?'⚑':'·'}</span></div>`).join(''):'<div class="person-row"><div class="person-avatar">?</div><div class="person-info"><b>Ninguém conhecido</b><small>Fale com quem cruzar seu caminho.</small></div></div>';
48:   }
49:   function renderCodex(){const met=Object.values(state.npcs).filter(n=>n.met);const people=met.length?met.map(n=>`<article class="codex-card"><span class="eyebrow">${esc(n.role.toUpperCase())} · ${n.age} ANOS</span><h3>${esc(n.name)}</h3><p><b>Aparência:</b> ${esc(n.look)}<br><b>Personalidade:</b> ${esc(n.personality)}<br><b>História:</b> ${esc(n.history)}<br><b>Objetivos:</b> ${esc(n.goals)}<br><b>Medos:</b> ${esc(n.fear)}<br><b>Desejos:</b> ${esc(n.desire)}<br><b>Conhecimentos:</b> ${esc(n.knowledge)}<br><b>Opinião:</b> ${esc(n.relation)}<br><b>Memórias:</b> ${n.memory.length?esc(n.memory.slice(-3).join(' ')):'Ainda não há lembranças compartilhadas.'}</p></article>`).join(''):'<article class="codex-card"><span class="eyebrow">PESSOAS</span><h3>Rostos por conhecer</h3><p>Personagens importantes entram no códice quando você os encontra. Cada um tem seus próprios desejos, medos e memórias.</p></article>';
50:     $('codexContent').innerHTML=`<div class="codex-grid">${regions.map(r=>`<article class="codex-card codex-region"><div class="region-name">${esc(r.name.toUpperCase())} · ${esc(r.city.toUpperCase())}</div><h3>${esc(r.tone.split(' · ')[0])}</h3><p><b>Cultura:</b> ${esc(r.culture)}<br><b>Fé:</b> ${esc(r.religion)}<br><b>Conflito:</b> ${esc(r.conflict)}<br><b>Criaturas:</b> ${esc(r.creatures)}<br><b>Facção:</b> ${esc(r.faction)}<br><b>Economia:</b> ${esc(r.economy)}<br><b>Rumor:</b> ${esc(r.event)}${state.secrets.includes(r.id)?`<br><b>Segredo:</b> ${esc(r.secret)}`:''}</p></article>`).join('')}${people}</div>`;
51:   }
52:   function startQuest(id){const q=state.quests.find(x=>x.id===id);if(!q||q.state!=='Disponível')return;q.state='Em andamento';q.note='Você decidiu seguir este fio.';addEntry(`Você registra <strong>${esc(q.title)}</strong> entre seus objetivos. Ninguém o obriga a continuar.`,{result:'FIO ACEITO'});toast('Novo fio registrado no diário.');render();}
53:   function roll(stat,difficulty=12){const d=Math.floor(Math.random()*20)+1,mod=Math.floor((state[stat]-10)/2),total=d+mod;return{d,total,success:total>=difficulty};}
54:   function gainXP(amount){state.xp+=amount;let leveled=false;while(state.xp>=state.level*100){state.xp-=state.level*100;state.level++;state.maxHp+=3;state.hp=state.maxHp;state.maxStamina+=2;state.stamina=state.maxStamina;state.might++;state.wit++;leveled=true;}return leveled;}
55:   function moveTime(minutes){state.time+=minutes;if(state.time>=24*60){state.day+=Math.floor(state.time/(24*60));state.time%=24*60;}}
56:   function recordEvent(text){state.events.push({day:state.day,text});if(state.events.length>80)state.events.shift();}
57:   function getNpc(text){const all=Object.values(state.npcs);let n=all.find(p=>p.met&&text.toLocaleLowerCase('pt-BR').includes(p.name.toLocaleLowerCase('pt-BR')));if(!n){const inRegion=all.filter(p=>p.region===state.region);n=inRegion.find(p=>!p.met)||all.find(p=>!p.met)||all[0];}return n;}
58:   function meet(n){if(!n)return; n.met=true;n.region=state.region;}
59:   function action(text){text=text.trim();if(!text)return;const lower=text.toLocaleLowerCase('pt-BR');
60:     if(/\b(viajo|viajar|parto|sigo para|vou para|caminho até|rumo a)\b/.test(lower)){buildMap();$('mapOverlay').classList.add('open');$('mapOverlay').setAttribute('aria-hidden','false');toast('Escolha um destino no mapa.');return;}
61:     moveTime(10+Math.floor(Math.random()*16));state.turn++;
62:     const r=currentRegion();let result='',outcome='';
63:     const talk=/\b(falo|convers|pergunto|perguntar|digo|dizer|negocio|persuad|ameaço|ameaçar|ment|convenc|ouço|escut|abordo)\b/.test(lower);
64:     const attack=/\b(ataco|atacar|golpe|luto|lutar|batalh|mato|matar|defendo|defender|disparo|flecha|combato|combater)\b/.test(lower);
65:     const stealth=/\b(escond|furtiv|esgueir|roub|arromb|invado|espio|espionar|engan|saboto|desço|descer)\b/.test(lower);
66:     const rest=/\b(descans|dorm|durmo|recuper|acamp|compro|comprar|vendo|vender|curar|poção|tônico)\b/.test(lower);
67:     const investigate=/\b(explor|investig|examino|examinar|procuro|busco|rastre|vasculh|estudo|observo)\b/.test(lower);
68:     if(talk){let npc=getNpc(lower);meet(npc);let check=roll('wit',11);let greet=npc.trust>1?'O reconhecimento suaviza o olhar.':npc.trust<0?'A mão se aproxima do cinto, sem chegar a tocá-lo.':'A pessoa mede suas palavras antes de responder.';
69:       if(/ameaç/.test(lower)){npc.trust=(npc.trust||0)-1;state.rep='Temido';outcome='A ameaça fica no ar. A confiança diminui.';result=`<strong>${esc(npc.name)}</strong> endurece o semblante. “Em Brumafria, quem ameaça acaba ouvindo passos atrás de si.” ${greet}`;}
70:       else if(/negoci|persuad|convenc/.test(lower)){if(check.success){npc.trust=(npc.trust||0)+1;state.gold+=3;outcome=`Teste de astúcia: ${check.total} — sucesso`;result=`<strong>${esc(npc.name)}</strong> considera sua proposta. Um acordo modesto é firmado; você recebe 3 moedas. “Não confunda um trato com amizade.”`; }else{outcome=`Teste de astúcia: ${check.total} — sucesso parcial`;result=`<strong>${esc(npc.name)}</strong> não aceita o acordo, mas revela uma pista: ${esc(r.event)}`;}}
71:       else if(/pergunt|ouço|escut|rumor|conversa/.test(lower)){result=`<strong>${esc(npc.name)}</strong> limpa as mãos no avental. “${esc(r.event)}” ${greet}`;outcome='Um rumor passa a fazer parte da sua memória.';if(!state.flags[`rumor-${r.id}`]){state.flags[`rumor-${r.id}`]=true;state.quests.push({id:`rumor-${r.id}`,title:`Ecos de ${r.city}`,giver:npc.name,kind:`RUMOR · ${r.name.toUpperCase()}`,desc:r.event,state:'Disponível',progress:0});}}
72:       else{result=`Você se aproxima de <strong>${esc(npc.name)}</strong>. ${esc(npc.look)} ${greet} “O que procura por estas bandas?”`;outcome='O encontro foi registrado no códice.';}
73:       npc.memory.push(`${state.day}/${timeText()}: ${text.slice(0,100)}`);if(npc.memory.length>15)npc.memory.shift();
74:     }else if(attack){let check=roll('might',12);state.stamina=Math.max(0,state.stamina-3);if(check.success){state.hp=Math.max(1,state.hp-(Math.random()<.25?2:0));const xp=18;const leveled=gainXP(xp);outcome=`Teste de vigor: ${check.total} — vitória · +${xp} XP${leveled?' · nível aumentado!':''}`;const foundItem=Math.random()<.5;result=`Seu movimento rompe o silêncio. A ameaça recua, deixando para trás ${foundItem?'uma presa de osso polido':'um punhado de moedas antigas'}. Você não sabe quem mais ouviu o combate.`;if(foundItem){state.items.push('Presa de osso');}else state.gold+=4;state.rep='Nome em circulação';}else{state.hp=Math.max(1,state.hp-4);outcome=`Teste de vigor: ${check.total} — revés · -4 vitalidade`;result=`A criatura lê seu movimento antes que você termine. Você recua com um corte superficial; o ruído se perde na névoa, mas não por muito tempo.`;}
75:     }else if(rest){if(/compr|vendo|vender/.test(lower)){if(state.gold>=5){state.gold-=5;state.items.push('Ração de viagem');result='O mercador pesa cinco moedas na palma e lhe entrega uma ração embrulhada em pano encerado.';outcome='−5 ouro · +1 ração de viagem';}else{result='O mercador olha para sua bolsa vazia. “Volte quando suas moedas fizerem mais barulho.”';outcome='Você não tem ouro suficiente.';}}else{state.hp=Math.min(state.maxHp,state.hp+7);state.stamina=state.maxStamina;result='Você encontra abrigo por algumas horas. O frio continua, mas suas mãos param de tremer e o fôlego retorna.';outcome='Vitalidade e fôlego recuperados.';}}
76:     else if(investigate||stealth){const check=roll('wit',stealth?14:11);if(check.success){let found;if(!state.secrets.includes(r.id)&&Math.random()<.48){state.secrets.push(r.id);found=`${r.secret}`;outcome=`Teste de astúcia: ${check.total} — descoberta · +12 XP`; }else{const loot=['Ervas secas','Moeda antiga','Fragmento de mapa','Fivela de prata'];const item=loot[Math.floor(Math.random()*loot.length)];found=`Você encontra ${item} entre os vestígios.`;state.items.push(item);outcome=`Teste de astúcia: ${check.total} — sucesso · +12 XP`;}
