(() => {
'use strict';
const SAVE_KEY='eclipse-veil-save-v1';
const $=id=>document.getElementById(id);
const species=[
 {name:'Lúmen',element:'Luz',color:'#f0cf75',glyph:'✦',habitat:'Clareiras de Lunária',desc:'Um pequeno espírito de luz que procura companhia.',forms:['Auríneo','Oráculo Solar'],pref:'gentileza'},
 {name:'Musguito',element:'Natureza',color:'#8fc486',glyph:'❀',habitat:'Bosque de Lunária',desc:'Brotos vivos escondem um coração curioso.',forms:['Raizal','Floravél'],pref:'fruta'},
 {name:'Brasalto',element:'Fogo',color:'#eb855b',glyph:'◆',habitat:'Ruínas quentes',desc:'Um lagarto de pedra com brasas sob as escamas.',forms:['Fornalha','Fênix de Cinza'],pref:'calor'},
 {name:'Córali',element:'Água',color:'#77bfca',glyph:'❧',habitat:'Rios e costa',desc:'Uma criatura de maré que coleciona ecos.',forms:['Maréu','Abissalume'],pref:'água'},
 {name:'Pedralume',element:'Terra',color:'#b8a274',glyph:'⬟',habitat:'Colinas de Auren',desc:'Pequeno guardião mineral de passos pacientes.',forms:['Granitouro','Montanhar'],pref:'pedra'},
 {name:'Vespira',element:'Vento',color:'#b6d6c3',glyph:'⌁',habitat:'Campos abertos',desc:'Uma dançarina alada que brinca com correntes de ar.',forms:['Ciclonejo','Asa-de-névoa'],pref:'liberdade'},
 {name:'Fulgurim',element:'Raio',color:'#e4df76',glyph:'ϟ',habitat:'Árvores antigas',desc:'Faíscas vivas que saltam entre raízes e galhos.',forms:['Troválio','Tempestário'],pref:'energia'},
 {name:'Névoaço',element:'Gelo',color:'#a7cbe0',glyph:'❄',habitat:'Montanhas frias',desc:'Um filhote espectral que deixa cristais no ar.',forms:['Glaciel','Aurora Boreal'],pref:'silêncio'},
 {name:'Umbri',element:'Trevas',color:'#a88bc4',glyph:'☾',habitat:'Ruínas sombrias',desc:'Uma sombra tímida que só aparece quando alguém precisa.',forms:['Noturno','Eclipsário'],pref:'confiança'},
 {name:'Runídeo',element:'Arcano',color:'#bd9cdb',glyph:'◇',habitat:'Locais de poder',desc:'Símbolos antigos flutuam ao redor deste ser.',forms:['Arcanis','Cronovél'],pref:'mistério'},
 {name:'Aurorim',element:'Luz',color:'#f0ba8a',glyph:'☼',habitat:'Planícies',desc:'Um cervo jovem com chifres que guardam o amanhecer.',forms:['Alvorada','Solstício'],pref:'aurora'},
 {name:'Lodossauro',element:'Terra',color:'#9b8769',glyph:'♧',habitat:'Pântanos',desc:'Um anfíbio antigo, coberto de líquens brilhantes.',forms:['Brejante','Raiz-Anciã'],pref:'chuva'}
];
const regions=[
 {id:'lunaria',name:'Floresta de Lunária',subtitle:'BOSQUE VIVO',color:'#294f3b',accent:'#a6c58e',symbol:'♧',cost:0,desc:'Raízes ancestrais, riachos e ruínas sob uma copa sem fim.',spawns:[0,1,2,6]},
 {id:'auren',name:'Planícies de Auren',subtitle:'CAMPOS DOURADOS',color:'#697044',accent:'#d9c17b',symbol:'⌁',cost:4,desc:'Campos abertos e trilhas antigas sob um céu vasto.',spawns:[4,5,10,1]},
 {id:'varkan',name:'Deserto de Varkan',subtitle:'DUNAS DE BRASA',color:'#805238',accent:'#e5a56b',symbol:'◇',cost:7,desc:'Dunas movediças escondem um templo de pedra vermelha.',spawns:[2,4,9,10]},
 {id:'frostheim',name:'Montanhas de Frostheim',subtitle:'FRONTEIRA GLACIAL',color:'#466775',accent:'#b1d6dc',symbol:'❄',cost:8,desc:'Picos nevados, lagos quietos e cavernas de cristal.',spawns:[7,4,5,9]},
 {id:'morgrath',name:'Pântano de Morgrath',subtitle:'ÁGUAS VELADAS',color:'#435342',accent:'#aec282',symbol:'☾',cost:7,desc:'Águas escuras guardam ruínas e coisas que ainda sonham.',spawns:[8,11,1,9]},
 {id:'azur',name:'Costa de Azur',subtitle:'MAR DE VIDRO',color:'#326172',accent:'#8fced0',symbol:'⚓',cost:9,desc:'Falésias azuis, enseadas escondidas e marés misteriosas.',spawns:[3,5,8,10]},
 {id:'terras',name:'Terras do Véu',subtitle:'FRATURA ARCANA',color:'#504268',accent:'#c9a7df',symbol:'✧',cost:12,desc:'A realidade ondula ao redor de portais antigos.',spawns:[9,8,6,0]},
 {id:'abismo',name:'Abismo Eterno',subtitle:'A RUPTURA',color:'#302f43',accent:'#c17c83',symbol:'◈',cost:0,desc:'O fim do caminho, onde a Grande Ruptura ainda respira.',spawns:[8,9,2,7]}
];
const makeCreature=(id,level=1)=>{const s=species[id];return{id:crypto.randomUUID?.()||`${Date.now()}-${Math.random()}`,species:id,name:s.name,form:s.name,element:s.element,color:s.color,glyph:s.glyph,level,xp:0,hp:22+level*4,maxHp:22+level*4,affinity:1,evolved:false};};
const initial=()=>({name:'Viajante',level:1,xp:0,hp:32,maxHp:32,stamina:100,gold:12,seals:3,fruit:2,region:'lunaria',x:0,y:0,day:1,time:8*60,team:[],reserve:[],codex:[],quests:[{id:'firstbond',title:'O vínculo desperto',desc:'Encontre e acolha o Vélion ferido junto às ruínas.',state:'Em andamento',kind:'PRINCIPAL'}],flags:{},story:[],kills:0});
let state;try{state=JSON.parse(localStorage.getItem(SAVE_KEY))||initial()}catch{state=initial()}
if(!state.flags)state.flags={};if(!state.quests)state.quests=[];if(!state.team)state.team=[];if(!state.reserve)state.reserve=[];if(!state.codex)state.codex=[];if(!state.region)state.region='lunaria';
let keys={},touch={},lastFrame=0,toastTimer,spawnedRegion='',enemies=[],pickups=[],props=[],particles=[],nearby=null,attackCooldown=0,enemyTick=0,interactCooldown=0,staminaRegen=0,dialogAction=null;
const canvas=$('gameCanvas'),ctx=canvas.getContext('2d');
const mapSize={w:1400,h:1000};let view={w:800,h:500,scale:1,camX:0,camY:0};
function currentRegion(){return regions.find(r=>r.id===state.region)||regions[0]}
function activeCreature(){return state.team[0]||null}
function save(){try{localStorage.setItem(SAVE_KEY,JSON.stringify(state));$('saveText').textContent='Salvo neste dispositivo';}catch{$('saveText').textContent='Falha ao salvar'}}
function toast(msg){const el=$('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2300)}
function log(text,result=''){state.story.push({text,result});if(state.story.length>35)state.story.shift();renderStory();save()}
function renderStory(){ $('storyFeed').innerHTML=state.story.slice(-5).reverse().map(x=>`<article class="story-entry"><p>${x.text}</p>${x.result?`<div class="entry-result">${x.result}</div>`:''}</article>`).join('') }
function addXP(n){state.xp+=n;while(state.xp>=state.level*80){state.xp-=state.level*80;state.level++;state.maxHp+=4;state.hp=state.maxHp;state.gold+=3;toast(`Nível ${state.level}! Vitalidade restaurada.`)} }
function ensureWorld(){if(spawnedRegion===state.region)return;spawnedRegion=state.region;enemies=[];pickups=[];props=[];const r=currentRegion();let seed=state.region.split('').reduce((a,c)=>a+c.charCodeAt(0),0);const rand=()=>{seed=(seed*9301+49297)%233280;return seed/233280};
 for(let i=0;i<36;i++){let x=rand()*mapSize.w,y=rand()*mapSize.h;if(Math.hypot(x-700,y-500)<130)continue;props.push({x,y,type:rand()<.72?'tree':'stone',size:18+rand()*22,variant:rand()})}
 for(let i=0;i<8;i++){const sp=r.spawns[i%r.spawns.length],x=130+rand()*1140,y=120+rand()*760,level=1+Math.floor(rand()*3);enemies.push({species:sp,x,y,hp:18+level*6,maxHp:18+level*6,level,alive:true,hostile:true,aggro:false,hit:0,seed:rand()*8,injured:false})}
 if(state.region==='lunaria'&&!state.flags.firstSeen){const sp=0;enemies.unshift({species:sp,x:780,y:500,hp:12,maxHp:26,level:1,alive:true,hostile:false,aggro:false,hit:0,injured:true,seed:0});}
 for(let i=0;i<13;i++){let x=90+rand()*1220,y=80+rand()*840;if(props.some(p=>Math.hypot(p.x-x,p.y-y)<40))continue;pickups.push({x,y,kind:i%4===0?'herb':'fruit',taken:false})}
 props.push({x:700,y:500,type:'ruin',size:74,variant:0});props.push({x:270,y:700,type:'shrine',size:26,variant:0});
}
function resize(){const rect=canvas.getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.max(1,rect.width*dpr);canvas.height=Math.max(1,rect.height*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);view.w=rect.width;view.h=rect.height;view.scale=Math.min(view.w/800,view.h/500);}
window.addEventListener('resize',resize);resize();
function worldToScreen(x,y){return{x:x-view.camX+view.w/2,y:y-view.camY+view.h/2}}
function setPanel(panel){document.querySelectorAll('.view').forEach(v=>v.classList.remove('active'));document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.panel===panel));const viewEl=$(`${panel}View`);if(viewEl)viewEl.classList.add('active');$('sidebar').classList.remove('open');if(panel==='team')renderTeam();if(panel==='codex')renderCodex();if(panel==='quests')renderQuests();if(panel==='inventory')renderInventory();if(panel==='map')renderMap();window.scrollTo(0,0)}
function getPlayer(){if(!state.x)state.x=700;if(!state.y)state.y=620;return{x:state.x,y:state.y}}
function nearestEnemy(max=70){const p=getPlayer();return enemies.filter(e=>e.alive).map(e=>({...e,d:Math.hypot(e.x-p.x,e.y-p.y)})).filter(e=>e.d<max).sort((a,b)=>a.d-b.d)[0]}
function nearbyObject(){const p=getPlayer();let candidates=[];enemies.filter(e=>e.alive).forEach(e=>candidates.push({type:'creature',obj:e,d:Math.hypot(e.x-p.x,e.y-p.y)}));pickups.filter(o=>!o.taken).forEach(o=>candidates.push({type:'pickup',obj:o,d:Math.hypot(o.x-p.x,o.y-p.y)}));props.filter(o=>['shrine','ruin'].includes(o.type)).forEach(o=>candidates.push({type:o.type,obj:o,d:Math.hypot(o.x-p.x,o.y-p.y)}));return candidates.filter(x=>x.d<66).sort((a,b)=>a.d-b.d)[0]||null}
function collides(x,y){if(x<25||y<25||x>mapSize.w-25||y>mapSize.h-25)return true;return props.some(p=>['tree','stone','ruin'].includes(p.type)&&Math.hypot(x-p.x,y-p.y)<(p.type==='ruin'?55:p.size*.65+13))}

