function escapeHTML(value){return String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function showDialog(title,body,actions=[{label:'Fechar',run:()=>closeDialog()}]){const box=$('dialog');box.innerHTML=`<h2>${title}</h2>${body}<div class="dialog-actions">${actions.map((a,i)=>`<button data-dialog-action="${i}" class="${a.secondary?'secondary':''}">${a.label}</button>`).join('')}</div>`;dialogAction=actions;$('dialogBackdrop').classList.add('open');$('dialogBackdrop').setAttribute('aria-hidden','false');box.querySelectorAll('[data-dialog-action]').forEach(b=>b.onclick=()=>actions[Number(b.dataset.dialogAction)]?.run())}
function closeDialog(){$('dialogBackdrop').classList.remove('open');$('dialogBackdrop').setAttribute('aria-hidden','true');dialogAction=null}
function addCodex(id){if(!state.codex.includes(id)){state.codex.push(id);toast(`${species[id].name} registrado no Bestiário`);renderCodex()}}
function completeQuest(id,reward){const q=state.quests.find(x=>x.id===id);if(!q||q.done)return;q.done=true;q.state='Concluída';state.gold+=reward.gold||0;state.seals+=reward.seals||0;addXP(reward.xp||0);if(reward.fruit)state.fruit+=reward.fruit;log(`Crônica concluída: ${q.title}.`,`+${reward.gold||0} Âmbar · +${reward.xp||0} XP`);if(id==='firstbond'&&!state.quests.some(x=>x.id==='trail'))state.quests.push({id:'trail',title:'Ecos na trilha',desc:'Derrote duas criaturas selvagens e explore as trilhas além da clareira.',state:'Em andamento',kind:'JORNADA'});renderQuests();save()}
function updateObjective(){const text=state.flags.firstBond?'Derrote criaturas e descubra as regiões de Elyndra':state.flags.firstSeen?'Aproxime-se do Vélion ferido e ofereça um vínculo':'Encontre o Vélion ferido junto às ruínas';$('objectiveText').textContent=text;$('bondText').textContent=state.flags.firstBond?'O primeiro vínculo foi selado. Outras criaturas aguardam nas trilhas.':'Um pequeno ser de luz aguarda ajuda perto das ruínas antigas.'}
function capture(enemy){if(!enemy?.alive)return;if(state.seals<1){toast('Você não tem selos. Recolha recursos ou visite um altar.');return}const s=species[enemy.species],chance=Math.min(.94,.28+(1-enemy.hp/enemy.maxHp)*.62+(enemy.injured?.24:0));state.seals--;addCodex(enemy.species);if(Math.random()<chance){enemy.alive=false;const c=makeCreature(enemy.species,enemy.level);c.hp=Math.max(1,Math.ceil(c.maxHp*.7));c.affinity=enemy.injured?3:1;const place=state.team.length<4?'team':'reserve';state[place].push(c);log(`${s.name} aceitou seu vínculo.`,place==='team'?'Entrou na equipe ativa.':'Enviado ao refúgio.');toast(`${s.name} agora caminha com você!`);if(enemy.injured&&!state.flags.firstBond){state.flags.firstBond=true;state.flags.firstSeen=true;completeQuest('firstbond',{gold:8,seals:2,xp:35,fruit:1})}else addXP(8);updateObjective();renderTeam();}else{enemy.aggro=true;enemy.hostile=true;toast(`${s.name} resistiu ao selo. Enfraqueça e tente outra vez.`);log(`O vínculo com ${s.name} não se firmou.`)}renderHUD();save()}
function interact(){if(interactCooldown>0)return;interactCooldown=.28;nearby=nearbyObject();if(!nearby){const p=getPlayer(),shrine=props.find(o=>o.type==='shrine'&&Math.hypot(o.x-p.x,o.y-p.y)<95);if(shrine){state.hp=state.maxHp;state.stamina=100;state.seals+=1;log('O altar desperta sob sua mão.','Vitalidade restaurada · +1 selo');toast('Altar ativado: saúde restaurada e +1 selo.');renderHUD();save();return}toast('Nada por perto para interagir.');return}
 const o=nearby.obj;if(nearby.type==='pickup'){o.taken=true;if(o.kind==='fruit'){state.fruit++;toast('Fruta silvestre recolhida.')}else{state.seals++;toast('Uma erva luminosa virou um selo.')}addXP(2);log('Você recolheu recursos da trilha.',o.kind==='fruit'?'+1 fruta':'+1 selo');renderHUD();save();return}
 if(nearby.type==='ruin'){if(!state.flags.ruins){state.flags.ruins=true;addXP(12);state.gold+=3;log('As runas despertam. Um mapa antigo aponta para terras distantes.','+3 Âmbar · +12 XP');toast('As ruínas revelaram uma rota no mapa.');}else toast('As runas já foram decifradas. Viaje pelo mapa para continuar.');renderHUD();save();return}
 if(nearby.type==='shrine'){state.hp=state.maxHp;state.stamina=100;state.seals++;toast('O altar restaurou sua vitalidade e concedeu um selo.');renderHUD();save();return}
 if(o.injured){state.flags.firstSeen=true;showDialog('Uma luz entre as ruínas',`<p>O pequeno <b>${species[o.species].name}</b> está ferido, mas não foge. Ele observa sua mão estendida. Você pode oferecer uma fruta para ganhar confiança ou tentar selar o vínculo agora.</p><p class="dialog-creature">Frutas: ${state.fruit} · Selos: ${state.seals}</p>`,[{label:'Oferecer fruta',run:()=>{closeDialog();if(state.fruit<1){toast('Você não tem frutas.');return}state.fruit--;o.hp=Math.max(1,o.hp);o.injured=true;o.friendly=true;state.seals++;toast('A criatura confia em você. +1 selo');log('Você cuidou do Vélion ferido.','Ele aguarda um vínculo.');renderHUD();save()}},{label:'Selar vínculo',run:()=>{closeDialog();capture(o)}},{label:'Depois',secondary:true,run:closeDialog}]);return}
 const s=species[o.species];showDialog(s.name,`<p>${s.desc}</p><p class="dialog-creature">${s.element} · Nv. ${o.level} · Vitalidade ${o.hp}/${o.maxHp}</p>`,[{label:'Tentar vínculo',run:()=>{closeDialog();capture(o)}},{label:'Fechar',secondary:true,run:closeDialog}]);}
function attack(){if(attackCooldown>0)return;attackCooldown=.42;const p=getPlayer(),target=nearestEnemy(112);if(!target){toast('Nenhuma criatura ao alcance. Aproxime-se de um Vélion.');return}const e=enemies.find(x=>x.x===target.x&&x.y===target.y)||target;let damage=8+state.level*2;const ally=activeCreature();if(ally&&ally.hp>0)damage+=Math.ceil(ally.level*1.7);e.hp=Math.max(0,e.hp-damage);e.hit=.24;e.aggro=true;particles.push({x:e.x,y:e.y-20,text:`-${damage}`,life:.7,color:'#f0c482'});if(e.hp<=0){e.alive=false;state.kills++;state.gold+=2+e.level;addXP(18+e.level*5);if(ally){ally.xp+=12;levelCreature(ally)}log(`${species[e.species].name} foi vencido.`,`+${2+e.level} Âmbar · +${18+e.level*5} XP`);if(state.kills>=2){const q=state.quests.find(x=>x.id==='trail');if(q&&!q.done)completeQuest('trail',{gold:6,seals:1,xp:25})}toast(`${species[e.species].name} recuou da trilha.`)}else toast(`Golpe certeiro: ${damage} de dano.`);renderHUD();save()}
