function renderTeam(){const all=[...state.team,...state.reserve];$('teamSummary').textContent=`${state.team.length}/4 na equipe · ${state.reserve.length} no refúgio`;$('teamCount').textContent=state.team.length;$('feedButton').textContent=`✦ Alimentar ativo · ${state.fruit} fruta${state.fruit===1?'':'s'}`;$('teamGrid').innerHTML=all.length?all.map(c=>{const active=state.team.some(x=>x.id===c.id),s=species[c.species];return `<article class="creature-card ${active&&state.team[0]?.id===c.id?'active-creature':''}"><div class="creature-head"><h3 style="color:${c.color}">${c.glyph} ${escapeHTML(c.form||c.name)}</h3><small>${escapeHTML(c.element)} · NÍVEL ${c.level}${c.evolved?' · EVOLUÍDO':''}</small></div><p>${s.desc}</p><div class="creature-meta">Vitalidade ${c.hp}/${c.maxHp} · Vínculo ${c.affinity}/5 · XP ${c.xp}/${c.level*24}</div><div class="meter"><i style="width:${100*c.hp/c.maxHp}%"></i></div><div class="card-actions">${active?`<button data-team="${c.id}" data-team-action="lead">${state.team[0]?.id===c.id?'Líder':'Liderar'}</button>`:`<button data-team="${c.id}" data-team-action="add">${state.team.length<4?'Adicionar':'Trocar líder'}</button>`}<button data-team="${c.id}" data-team-action="feed">Alimentar (1 fruta)</button><button data-team="${c.id}" data-team-action="release">Liberar</button></div></article>`}).join(''):'<article class="creature-card"><h3>Nenhum vínculo ainda</h3><p>Explore a floresta, aproxime-se de uma criatura e use E para interagir ou K para tentar um vínculo.</p></article>'; $('teamGrid').querySelectorAll('[data-team-action]').forEach(b=>b.onclick=()=>teamAction(b.dataset.team,b.dataset.teamAction));}
