}
function drawProp(o,s){ctx.save();if(o.type==='tree'){ctx.fillStyle='#17291f';ctx.beginPath();ctx.ellipse(s.x,s.y+7,o.size*.48,o.size*.2,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#513e2c';ctx.fillRect(s.x-3,s.y-4,6,18);ctx.fillStyle=['#365b40','#3e6844','#31543b'][Math.floor(o.variant*3)];ctx.beginPath();ctx.arc(s.x,s.y-8,o.size*.52,0,Math.PI*2);ctx.fill();ctx.fillStyle='#71905a55';ctx.beginPath();ctx.arc(s.x-o.size*.14,s.y-o.size*.2,o.size*.22,0,Math.PI*2);ctx.fill()}else if(o.type==='stone'){ctx.fillStyle='#777b68';ctx.beginPath();ctx.ellipse(s.x,s.y,o.size*.5,o.size*.35,-.18,0,Math.PI*2);ctx.fill();ctx.fillStyle='#bec39c44';ctx.fillRect(s.x-6,s.y-4,8,2)}else if(o.type==='ruin'){ctx.fillStyle='#4c4a3b';ctx.fillRect(s.x-34,s.y-20,68,42);ctx.fillStyle='#777050';ctx.fillRect(s.x-27,s.y-31,10,49);ctx.fillRect(s.x+17,s.y-31,10,49);ctx.fillRect(s.x-31,s.y-36,64,8);ctx.fillStyle='#d8be7955';ctx.fillRect(s.x-3,s.y-12,6,22);ctx.fillRect(s.x-11,s.y-4,22,4)}else if(o.type==='shrine'){ctx.fillStyle='#d7bd77';ctx.shadowColor='#d7bd77';ctx.shadowBlur=12;ctx.beginPath();ctx.arc(s.x,s.y,8,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#413e31';ctx.fillRect(s.x-12,s.y+8,24,5)}ctx.restore()}
