let soundOn=false,audioContext=null;
function playTone(freq=440,duration=.06){if(!soundOn)return;try{audioContext=audioContext||new(window.AudioContext||window.webkitAudioContext)();const osc=audioContext.createOscillator(),gain=audioContext.createGain();osc.frequency.value=freq;gain.gain.setValueAtTime(.035,audioContext.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audioContext.currentTime+duration);osc.connect(gain);gain.connect(audioContext.destination);osc.start();osc.stop(audioContext.currentTime+duration)}catch{}}
function tick(dt){if(document.hidden)return;ensureWorld();if($('dialogBackdrop').classList.contains('open'))return;const playing=$('worldView').classList.contains('active');if(!playing)return;const p=getPlayer();let dx=(keys.ArrowRight||keys.d||touch.right?1:0)-(keys.ArrowLeft||keys.a||touch.left?1:0),dy=(keys.ArrowDown||keys.s||touch.down?1:0)-(keys.ArrowUp||keys.w||touch.up?1:0);const moving=dx||dy;if(moving){const len=Math.hypot(dx,dy);dx/=len;dy/=len;let speed=keys.Shift&&state.stamina>0?218:158;if(speed>160)state.stamina=Math.max(0,state.stamina-dt*20);const nx=p.x+dx*speed*dt,ny=p.y+dy*speed*dt;if(!collides(nx,p.y))state.x=nx;if(!collides(state.x,ny))state.y=ny;state.time=(state.time+dt*2.7)%1440;staminaRegen=0}else{staminaRegen+=dt;if(staminaRegen>.6)state.stamina=Math.min(100,state.stamina+dt*9);state.time=(state.time+dt*.65)%1440}
