(() => {
'use strict';
const SAVE_KEY='eclipse-veil-save-v1';
const $=id=>document.getElementById(id);
const canvas=$('gameCanvas'),ctx=canvas.getContext('2d');
const species=[
 {name:'Lúmen',element:'Luz',color:'#f0cf75',glyph:'✦',habitat:'Clareiras de Lunária',desc:'Um pequeno espírito de luz que procura companhia.',forms:['Auríneo','Oráculo Solar']},
 {name:'Musguito',element:'Natureza',color:'#8fc486',glyph:'❀',habitat:'Bosque de Lunária',desc:'Brotos vivos escondem um coração curioso.',forms:['Raizal','Floravél']},
 {name:'Brasalto',element:'Fogo',color:'#eb855b',glyph:'◆',habitat:'Ruínas quentes',desc:'Um lagarto de pedra com brasas sob as escamas.',forms:['Fornalha','Fênix de Cinza']},
 {name:'Córali',element:'Água',color:'#77bfca',glyph:'❧',habitat:'Rios e costa',desc:'Uma criatura de maré que coleciona ecos.',forms:['Maréu','Abissalume']},
 {name:'Pedralume',element:'Terra',color:'#b8a274',glyph:'⬟',habitat:'Colinas de Auren',desc:'Pequeno guardião mineral de passos pacientes.',forms:['Granitouro','Montanhar']},
 {name:'Vespira',element:'Vento',color:'#b6d6c3',glyph:'⌁',habitat:'Campos abertos',desc:'Uma dançarina alada que brinca com correntes de vento.',forms:['Ventália','Tempespria']},
 {name:'Umbri',element:'Sombra',color:'#a995c9',glyph:'◐',habitat:'Bosques ao anoitecer',desc:'Uma sombra curiosa que imita os passos de quem passa.',forms:['Noctírio','Eclipsal']},
 {name:'Faísca',element:'Raio',color:'#e3d46f',glyph:'ϟ',habitat:'Picos de Auren',desc:'Um filhote elétrico que ilumina a trilha com saltos.',forms:['Trovino','Relâmpago']},
 {name:'Geódia',element:'Cristal',color:'#d99ec2',glyph:'◇',habitat:'Grutas de cristal',desc:'Uma criatura facetada que guarda memórias em suas pedras.',forms:['Prismal','Catedraluz']},
 {name:'Brumelo',element:'Névoa',color:'#a8b8ba',glyph:'☁',habitat:'Pântanos de Nym',desc:'Um ser macio que aparece quando a manhã ainda dorme.',forms:['Nebulume','Névoa-Régia']},
 {name:'Fornalha',element:'Fogo',color:'#df795a',glyph:'♨',habitat:'Fendas vulcânicas',desc:'Uma chama antiga que aprendeu a caminhar sobre cinzas.',forms:['Cinzassol','Vulcárion']},
 {name:'Náutilo',element:'Água',color:'#80c9d1',glyph:'❂',habitat:'Costa de Azur',desc:'Um viajante marinho que carrega pequenas conchas de lembrança.',forms:['Maré-Coroa','Abissalume']}
];
const regions=[
 {id:'lunaria',name:'Floresta de Lunária',subtitle:'Bosque vivo',desc:'Clareiras antigas e raízes que sussurram.',color:'#263d2d',accent:'#adc58a',symbol:'❧',cost:0,wild:[0,1,5,6]},
 {id:'auren',name:'Colinas de Auren',subtitle:'Pedra e vento',desc:'Trilhas altas sob um céu amplo.',color:'#514536',accent:'#d6bb83',symbol:'⬟',cost:3,wild:[4,5,7,2]},
 {id:'nym',name:'Pântanos de Nym',subtitle:'Bruma baixa',desc:'Águas quietas e luzes que flutuam.',color:'#304744',accent:'#9dc6bd',symbol:'☁',cost:4,wild:[3,6,9,1]},
 {id:'azur',name:'Costa de Azur',subtitle:'Maré de vidro',desc:'Praias de pedra e enseadas brilhantes.',color:'#294754',accent:'#8ec9d5',symbol:'❧',cost:5,wild:[3,5,11,0]},
 {id:'cineria',name:'Campos de Cinéria',subtitle:'Terra morna',desc:'Ruínas vulcânicas dormem sob a relva.',color:'#513a32',accent:'#df9a75',symbol:'◆',cost:6,wild:[2,4,10,7]},
 {id:'cristal',name:'Grutas Prismáticas',subtitle:'Eco de cristal',desc:'Veios coloridos guardam histórias antigas.',color:'#49394d',accent:'#d5a5d0',symbol:'◇',cost:7,wild:[8,6,9,4]},
 {id:'frostheim',name:'Véus de Frostheim',subtitle:'Geada eterna',desc:'Uma planície branca sob auroras distantes.',color:'#3c5056',accent:'#c4d9d4',symbol:'✧',cost:8,wild:[5,7,8,11]},
 {id:'abismo',name:'Abismo do Véu',subtitle:'Além das runas',desc:'O mundo se dobra onde o Véu é mais fino.',color:'#302b46',accent:'#c4a8df',symbol:'◐',cost:10,wild:[6,8,9,10,11]}
];
const initial=()=>({name:'Viajante',region:'lunaria',x:700,y:620,hp:30,maxHp:30,stamina:100,level:1,xp:0,gold:12,seals:3,fruit:2,kills:0,day:1,time:480,team:[],reserve:[],codex:[],flags:{},quests:[{id:'firstbond',title:'Um primeiro vínculo',desc:'Encontre o Vélion ferido nas ruínas e conquiste sua confiança.',state:'Em andamento',kind:'PRIMEIRO FIO',done:false}],story:[]});
function load(){try{const raw=localStorage.getItem(SAVE_KEY);return raw?{...initial(),...JSON.parse(raw)}:initial()}catch{return initial()}}
let state=load(),keys={},touch={},view={w:800,h:500,camX:700,camY:620},mapSize={w:1600,h:1200};
let props=[],pickups=[],enemies=[],particles=[],spawnedRegion='',nearby=null,lastSave=0,lastFrame=-1,enemyTick=0,attackCooldown=0,interactCooldown=0,staminaRegen=0,toastTimer=0;
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function currentRegion(){return regions.find(r=>r.id===state.region)||regions[0]}
function getPlayer(){return{x:state.x,y:state.y}}
function makeCreature(id,level=1){const s=species[id];return{id:`v${Date.now().toString(36)}${Math.random().toString(36).slice(2,7)}`,species:id,name:s.name,element:s.element,glyph:s.glyph,color:s.color,level,xp:0,hp:24+level*5,maxHp:24+level*5,affinity:1,evolved:false,form:''}}
function activeCreature(){return state.team[0]||null}
function save(){try{localStorage.setItem(SAVE_KEY,JSON.stringify(state));$('saveText').textContent='Salvo neste dispositivo';lastSave=performance.now()}catch{$('saveText').textContent='Não foi possível salvar'}}
function scheduleSave(){if(performance.now()-lastSave>1200)save()}
function toast(message){const el=$('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2400)}
function log(text,result=''){state.story.unshift({text,result});state.story=state.story.slice(0,6);renderStory()}
function renderStory(){if(!$('storyFeed'))return;$('storyFeed').innerHTML=state.story.map((x,i)=>`<div class="story-entry ${i?'':'latest'}"><b>${esc(x.text)}</b>${x.result?`<small>${esc(x.result)}</small>`:''}</div>`).join('')||'<div class="story-entry">A trilha espera por você.</div>'}
function addXP(n){state.xp+=n;while(state.xp>=state.level*80){state.xp-=state.level*80;state.level++;state.maxHp+=5;state.hp=state.maxHp;state.gold+=3;toast(`Você alcançou o nível ${state.level}! +3 Âmbar`);log(`Sua jornada amadureceu.`,`Nível ${state.level} · vitalidade restaurada`)}renderHUD()}
function levelCreature(c){while(c.xp>=c.level*24){c.xp-=c.level*24;c.level++;c.maxHp+=6;c.hp=Math.min(c.maxHp,c.hp+8);toast(`${c.name} alcançou o nível ${c.level}!`)}if(c.level>=5&&!c.evolved)offerEvolution(c)}
function resize(){const rect=canvas.getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,2);view.w=Math.max(1,rect.width);view.h=Math.max(1,rect.height);canvas.width=Math.round(view.w*dpr);canvas.height=Math.round(view.h*dpr);ctx.setTransform(dpr,0,0,dpr,0,0)}
new ResizeObserver(resize).observe(canvas);resize();
function rand(seed){let x=Math.sin(seed*127.1+311.7)*43758.5453;return x-Math.floor(x)}
function ensureWorld(){if(spawnedRegion===state.region)return;spawnedRegion=state.region;props=[];pickups=[];enemies=[];const rid=regions.findIndex(r=>r.id===state.region);for(let i=0;i<48;i++){let x=70+rand(i+rid*77)*1460,y=70+rand(i+rid*113+11)*1060;if(Math.hypot(x-700,y-620)<105)continue;props.push({x,y,size:20+rand(i+33)*28,type:rand(i+8)>.22?'tree':'stone',variant:rand(i+29)})}
 props.push({type:'ruin',x:890,y:545,size:42},{type:'shrine',x:680,y:710,size:20});for(let i=0;i<30;i++){const x=80+rand(i+rid*21+400)*1440,y=80+rand(i+rid*41+800)*1040;if(Math.hypot(x-700,y-620)>100)pickups.push({x,y,kind:rand(i+rid*19+900)>.55?'fruit':'herb',taken:false})}
 const r=currentRegion();r.wild.forEach((id,i)=>{let x=160+rand(i+rid*88+200)*1280,y=140+rand(i+rid*79+300)*920;if(Math.hypot(x-700,y-620)<110){x+=230}enemies.push({species:id,x,y,level:1+Math.floor(rand(i+rid*31+600)*Math.min(5,state.level+2)),hp:26,maxHp:26,alive:true,hostile:false,aggro:false,injured:false,seed:i+rid*5})});if(state.region==='lunaria'&&!state.flags.firstBond){enemies.unshift({species:0,x:890,y:545,level:1,hp:14,maxHp:14,alive:true,hostile:false,aggro:false,injured:true,friendly:true,seed:99})}}
function worldToScreen(x,y){return{x:x-view.camX+view.w/2,y:y-view.camY+view.h/2}}
function collides(x,y){if(x<20||y<25||x>mapSize.w-20||y>mapSize.h-20)return true;return props.some(o=>o.type!=='shrine'&&Math.hypot(x-o.x,y-o.y)<o.size*.42+8)}
function nearestEnemy(distance=75){const p=getPlayer();return enemies.filter(e=>e.alive&&Math.hypot(e.x-p.x,e.y-p.y)<distance).sort((a,b)=>Math.hypot(a.x-p.x,a.y-p.y)-Math.hypot(b.x-p.x,b.y-p.y))[0]||null}
function nearbyObject(){const p=getPlayer();let list=[];for(const e of enemies)if(e.alive&&Math.hypot(e.x-p.x,e.y-p.y)<65)list.push({type:'creature',obj:e,d:Math.hypot(e.x-p.x,e.y-p.y)});for(const o of pickups)if(!o.taken&&Math.hypot(o.x-p.x,o.y-p.y)<48)list.push({type:'pickup',obj:o,d:Math.hypot(o.x-p.x,o.y-p.y)});for(const o of props)if(['ruin','shrine'].includes(o.type)&&Math.hypot(o.x-p.x,o.y-p.y)<65)list.push({type:o.type,obj:o,d:Math.hypot(o.x-p.x,o.y-p.y)});return list.sort((a,b)=>a.d-b.d)[0]||null}
function setPanel(panel){const ids={world:'worldView',team:'teamView',codex:'codexView',quests:'questsView',inventory:'inventoryView',map:'mapView'};Object.entries(ids).forEach(([key,id])=>$(id).classList.toggle('active',key===panel));document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.panel===panel));$('sidebar').classList.remove('open');if(panel==='team')renderTeam();if(panel==='codex')renderCodex();if(panel==='quests')renderQuests();if(panel==='inventory')renderInventory();if(panel==='map')renderMap()}

input.newString:
function setPanel(panel){const ids={world:'worldView',team:'teamView',codex:'codexView',quests:'questsView',inventory:'inventoryView',map:'mapView'};Object.entries(ids).forEach(([key,id])=>$(id).classList.toggle('active',key===panel));document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.panel===panel));$('sidebar').classList.remove('open');if(panel==='team')renderTeam();if(panel==='codex')renderCodex();if(panel==='quests')renderQuests();if(panel==='inventory')renderInventory();if(panel==='map')renderMap()}
function showDialog(title,body,actions=[{label:'Fechar',run:closeDialog}]){const box=$('dialog');box.innerHTML=`<h2>${title}</h2>${body}<div class="dialog-actions">${actions.map((a,i)=>`<button data-dialog-action="${i}" class="${a.secondary?'secondary':''}">${a.label}</button>`).join('')}</div>`;$('dialogBackdrop').classList.add('open');$('dialogBackdrop').setAttribute('aria-hidden','false');box.querySelectorAll('[data-dialog-action]').forEach(b=>b.onclick=()=>actions[Number(b.dataset.dialogAction)]?.run())}
function closeDialog(){$('dialogBackdrop').classList.remove('open');$('dialogBackdrop').setAttribute('aria-hidden','true')}
function addCodex(id){if(!state.codex.includes(id)){state.codex.push(id);toast(`${species[id].name} registrado no Bestiário`);renderCodex()}}
function completeQuest(id,reward={}){const q=state.quests.find(x=>x.id===id);if(!q||q.done)return;q.done=true;q.state='Concluída';state.gold+=reward.gold||0;state.seals+=reward.seals||0;state.fruit+=reward.fruit||0;addXP(reward.xp||0);log(`Crônica concluída: ${q.title}.`,`+${reward.gold||0} Âmbar · +${reward.xp||0} XP`);if(id==='firstbond'&&!state.quests.some(x=>x.id==='trail'))state.quests.push({id:'trail',title:'Ecos na trilha',desc:'Derrote duas criaturas selvagens e explore as trilhas além da clareira.',state:'Em andamento',kind:'JORNADA',done:false});renderQuests();save()}
function updateObjective(){const text=state.flags.firstBond?'Derrote criaturas e descubra as regiões de Elyndra':state.flags.firstSeen?'Aproxime-se do Vélion ferido e ofereça um vínculo':'Encontre o Vélion ferido junto às ruínas';$('objectiveText').textContent=text;$('bondText').textContent=state.flags.firstBond?'O primeiro vínculo foi selado. Outras criaturas aguardam nas trilhas.':'Um pequeno ser de luz aguarda ajuda perto das ruínas antigas.'}
function capture(enemy){if(!enemy?.alive)return;if(state.seals<1){toast('Você não tem selos. Recolha recursos ou visite um altar.');return}const s=species[enemy.species];const chance=Math.min(.94,.28+(1-enemy.hp/enemy.maxHp)*.62+(enemy.injured?.24:0)+(enemy.friendly?.2:0));state.seals--;addCodex(enemy.species);if(Math.random()<chance){enemy.alive=false;const c=makeCreature(enemy.species,enemy.level);c.hp=Math.max(1,Math.ceil(c.maxHp*.7));c.affinity=enemy.friendly?3:1;const place=state.team.length<4?'team':'reserve';state[place].push(c);log(`${s.name} aceitou seu vínculo.`,place==='team'?'Entrou na equipe ativa.':'Enviado ao refúgio.');toast(`${s.name} agora caminha com você!`);if(enemy.injured&&!state.flags.firstBond){state.flags.firstBond=true;state.flags.firstSeen=true;completeQuest('firstbond',{gold:8,seals:2,xp:35,fruit:1})}else addXP(8);updateObjective();renderTeam()}else{enemy.aggro=true;enemy.hostile=true;toast(`${s.name} resistiu ao selo. Enfraqueça e tente outra vez.`);log(`O vínculo com ${s.name} não se firmou.`)}renderHUD();save()}
function interact(){if(interactCooldown>0)return;interactCooldown=.3;nearby=nearbyObject();if(!nearby){toast('Nada por perto para interagir.');return}const o=nearby.obj;if(nearby.type==='pickup'){o.taken=true;if(o.kind==='fruit'){state.fruit++;toast('Fruta silvestre recolhida.')}else{state.flags.herbs=(state.flags.herbs||0)+1;state.seals++;toast('Erva luminosa recolhida: +1 selo.')}addXP(2);log('Você recolheu recursos da trilha.',o.kind==='fruit'?'+1 fruta':'+1 selo');renderInventory();renderHUD();save();return}if(nearby.type==='ruin'){if(!state.flags.ruins){state.flags.ruins=true;addXP(12);state.gold+=3;log('As runas despertam. Um mapa antigo aponta para terras distantes.','+3 Âmbar · +12 XP');toast('As ruínas revelaram uma rota no mapa.');renderMap()}else toast('As runas já foram decifradas. Viaje pelo mapa para continuar.');renderHUD();save();return}if(nearby.type==='shrine'){state.hp=state.maxHp;state.stamina=100;state.seals++;toast('O altar restaurou sua vitalidade e concedeu um selo.');renderHUD();save();return}if(o.injured){state.flags.firstSeen=true;showDialog('Uma luz entre as ruínas',`<p>O pequeno <b>${species[o.species].name}</b> está ferido, mas não foge. Você pode oferecer uma fruta para ganhar confiança ou tentar selar o vínculo agora.</p><p class="dialog-creature">Frutas: ${state.fruit} · Selos: ${state.seals}</p>`,[{label:'Oferecer fruta',run:()=>{closeDialog();if(state.fruit<1){toast('Você não tem frutas.');return}state.fruit--;o.hp=Math.max(1,o.hp);o.friendly=true;state.seals++;toast('A criatura confia em você. +1 selo');log('Você cuidou do Vélion ferido.','Ele aguarda um vínculo.');renderHUD();save()}},{label:'Selar vínculo',run:()=>{closeDialog();capture(o)}},{label:'Depois',secondary:true,run:closeDialog}]);return}const s=species[o.species];showDialog(s.name,`<p>${s.desc}</p><p class="dialog-creature">${s.element} · Nv. ${o.level} · Vitalidade ${o.hp}/${o.maxHp}</p>`,[{label:'Tentar vínculo',run:()=>{closeDialog();capture(o)}},{label:'Fechar',secondary:true,run:closeDialog}])}
function attack(){if(attackCooldown>0)return;attackCooldown=.42;const target=nearestEnemy(112);if(!target){toast('Nenhuma criatura ao alcance. Aproxime-se de um Vélion.');return}const damage=8+state.level*2+(activeCreature()?.hp>0?Math.ceil(activeCreature().level*1.7):0);target.hp=Math.max(0,target.hp-damage);target.aggro=true;target.hostile=true;particles.push({x:target.x,y:target.y-20,text:`-${damage}`,life:.7,color:'#f0c482'});if(target.hp<=0){target.alive=false;state.kills++;state.gold+=2+target.level;addXP(18+target.level*5);const ally=activeCreature();if(ally){ally.xp+=12;levelCreature(ally)}log(`${species[target.species].name} foi vencido.`,`+${2+target.level} Âmbar · +${18+target.level*5} XP`);if(state.kills>=2){const q=state.quests.find(x=>x.id==='trail');if(q&&!q.done)completeQuest('trail',{gold:6,seals:1,xp:25})}toast(`${species[target.species].name} recuou da trilha.`)}else toast(`Golpe certeiro: ${damage} de dano.`);renderHUD();save()}
function useCapture(){const target=nearestEnemy(130);if(!target){toast('Aproxime-se de uma criatura para selar um vínculo.');return}capture(target)}
function offerEvolution(c){if(c.evolved)return;const s=species[c.species];showDialog(`O vínculo de ${c.name} floresce`,`<p>Seu companheiro está pronto para evoluir. Escolha um caminho; esta decisão define sua forma e não pode ser desfeita.</p><p class="dialog-creature">A evolução aumenta atributos e muda a aparência.</p>`,s.forms.map((form,i)=>({label:form,run:()=>{c.form=form;c.evolved=true;c.maxHp+=18;c.hp=c.maxHp;c.color=i===0?'#d8bd79':'#a98bd1';closeDialog();toast(`${c.name} evoluiu para ${form}!`);log(`${c.name} tomou um novo caminho.`,`Evoluiu para ${form}`);renderTeam();renderHUD();save()}})).concat([{label:'Mais tarde',secondary:true,run:closeDialog}]))}
function feedActive(){const c=activeCreature();if(!c){toast('Você ainda não tem um Vélion na equipe.');return}if(state.fruit<1){toast('Sem frutas. Procure pelos pontos brilhantes na trilha.');return}if(c.hp>=c.maxHp&&c.affinity>=5){toast(`${c.name} já está saciado e saudável.`);return}state.fruit--;c.hp=Math.min(c.maxHp,c.hp+Math.ceil(c.maxHp*.35));c.affinity=Math.min(5,c.affinity+1);c.xp+=12;levelCreature(c);toast(`${c.name} recuperou forças e ganhou confiança.`);log(`Você compartilhou uma fruta com ${c.name}.`,`Vitalidade recuperada · Vínculo ${c.affinity}/5`);renderHUD();renderTeam();save()}

