function feedActive(){const c=activeCreature();if(!c){toast('Você ainda não tem um Vélion na equipe.');return}if(state.fruit<1){toast('Sem frutas. Procure pelos pontos brilhantes na trilha.');return}if(c.hp>=c.maxHp&&c.affinity>=5){toast(`${c.name} já está saciado e saudável.`);return}state.fruit--;c.hp=Math.min(c.maxHp,c.hp+Math.ceil(c.maxHp*.35));c.affinity=Math.min(5,c.affinity+1);c.xp+=12;levelCreature(c);toast(`${c.name} recuperou forças e ganhou confiança.`);log(`Você compartilhou uma fruta com ${c.name}.`,`Vitalidade recuperada · Vínculo ${c.affinity}/5`);renderHUD();renderTeam();save()}
function renderTeam(){const all=[...state.team,...state.reserve];$('teamSummary').textContent=`${state.team.length}/4 na equipe · ${state.reserve.length} no refúgio`;$('teamCount').textContent=state.team.length;$('feedButton').textContent=`✦ Alimentar ativo · ${state.fruit} fruta${state.fruit===1?'':'s'}`;$('teamGrid').innerHTML=all.length?all.map(c=>{const active=state.team.some(x=>x.id===c.id),leader=state.team[0]?.id===c.id,s=species[c.species];return `<article class="creature-card ${leader?'active-creature':''}"><div class="creature-head"><h3 style="color:${c.color}">${c.glyph} ${esc(c.form||c.name)}</h3><small>${esc(c.element)} · NÍVEL ${c.level}${c.evolved?' · EVOLUÍDO':''}</small></div><p>${esc(s.desc)}</p><div class="creature-meta">Vitalidade ${c.hp}/${c.maxHp} · Vínculo ${c.affinity}/5 · XP ${c.xp}/${c.level*24}</div><div class="meter"><i style="width:${100*c.hp/c.maxHp}%"></i></div><div class="card-actions">${active?`<button data-team="${c.id}" data-team-action="lead">${leader?'Líder':'Liderar'}</button>`:`<button data-team="${c.id}" data-team-action="add">${state.team.length<4?'Adicionar':'Trocar líder'}</button>`}<button data-team="${c.id}" data-team-action="feed">Alimentar (1 fruta)</button><button data-team="${c.id}" data-team-action="release">Liberar</button></div></article>`}).join(''):'<article class="creature-card"><h3>Nenhum vínculo ainda</h3><p>Explore a floresta, aproxime-se de uma criatura e use E para interagir ou K para tentar um vínculo.</p></article>';$('teamGrid').querySelectorAll('[data-team-action]').forEach(b=>b.onclick=()=>teamAction(b.dataset.team,b.dataset.teamAction))}
function teamAction(id,action){let idx=state.team.findIndex(c=>c.id===id),from='team';if(idx<0){idx=state.reserve.findIndex(c=>c.id===id);from='reserve'}if(idx<0)return;const list=state[from],c=list[idx];if(action==='feed'){if(state.fruit<1){toast('Você não tem frutas.');return}state.fruit--;c.hp=Math.min(c.maxHp,c.hp+Math.ceil(c.maxHp*.35));c.affinity=Math.min(5,c.affinity+1);c.xp+=12;levelCreature(c);renderTeam();renderHUD();save();return}if(action==='release'){showDialog('Desfazer vínculo?',`<p>${esc(c.form||c.name)} retornará à natureza. Essa ação não pode ser desfeita.</p>`,[{label:'Liberar',run:()=>{list.splice(idx,1);closeDialog();renderTeam();renderHUD();save();toast('O Vélion foi libertado.')}},{label:'Cancelar',secondary:true,run:closeDialog}]);return}if(action==='lead'){list.splice(idx,1);if(from==='reserve'&&state.team.length>=4){state.reserve.push(state.team.pop())}state.team.unshift(c)}else if(action==='add'){if(state.team.length<4){state.reserve.splice(idx,1);state.team.push(c)}else{const old=state.team.shift();state.reserve.push(old);state.reserve.splice(state.reserve.indexOf(c),1);state.team.push(c)}}renderTeam();renderHUD();save()}
function renderCodex(){const query=$('codexSearch').value.trim().toLocaleLowerCase('pt-BR'),seen=state.codex;$('codexCount').textContent=`${seen.length} de ${species.length} espécies registradas`;$('codexGrid').innerHTML=species.filter(s=>!query||`${s.name} ${s.element} ${s.habitat}`.toLocaleLowerCase('pt-BR').includes(query)).map(s=>{const index=species.indexOf(s),found=seen.includes(index),c=state.team.find(x=>x.species===index)||state.reserve.find(x=>x.species===index);return `<article class="codex-card"><span class="eyebrow">${found?esc(s.element.toUpperCase()):'REGISTRO SELADO'}</span><h3 style="color:${found?s.color:'#737b73'}">${found?s.glyph:'?'} ${found?esc(c?.form||s.name):'Espécie desconhecida'}</h3><p>${found?`${esc(s.desc)}<br><b>Habitat:</b> ${esc(s.habitat)}<br><b>Evoluções:</b> ${s.forms.map(esc).join(' / ')}`:'Encontre esta criatura em uma região de Elyndra para revelar seu registro.'}</p></article>`}).join('')}
function renderQuests(){$('questCount').textContent=state.quests.filter(q=>!q.done).length;$('questGrid').innerHTML=state.quests.length?state.quests.map(q=>`<article class="quest-card"><span class="eyebrow">${esc(q.kind||'JORNADA')} · ${q.done?'CONCLUÍDA':'EM ABERTO'}</span><h3>${esc(q.title)}</h3><p>${esc(q.desc)}</p>${q.done?'<b>✓ Promessa cumprida</b>':''}</article>`).join(''):'<article class="quest-card"><h3>Sem crônicas ativas</h3><p>Explore Elyndra para descobrir novos fios.</p></article>';$('activeQuests').innerHTML=state.quests.filter(q=>!q.done).slice(0,2).map(q=>`<div class="mini-quest"><b>${esc(q.title)}</b><small>${esc(q.desc)}</small></div>`).join('')||'<p class="rail-copy">Todas as promessas foram cumpridas.</p>'}
function renderInventory(){$('inventoryGrid').innerHTML=[['Selos de vínculo',state.seals,'Usados para acolher criaturas.'],['Frutas silvestres',state.fruit,'Recuperam Vélions e fortalecem o vínculo.'],['Âmbar',state.gold,'Moeda usada para viajar entre regiões.'],['Ervas luminosas',state.flags.herbs||0,'Encontradas pelo mundo; cada uma também vale um selo.'],['Vélions vencidos',state.kills,'Criaturas afastadas da trilha.'],['Dia de jornada',state.day,'O tempo passa enquanto você explora.']].map(([name,n,desc])=>`<article class="inventory-card"><b>${esc(name)}</b><p>${esc(desc)}</p><strong>${n}</strong></article>`).join('')}
function renderMap(){$('regionGrid').innerHTML=regions.map(r=>{const current=r.id===state.region,unlocked=r.cost===0||state.flags.ruins||state.gold>=r.cost;return `<button class="region-card ${current?'current':''}" data-region="${r.id}" style="background:linear-gradient(135deg,${r.color}66,#171f1b 74%)" ${!unlocked||current?'disabled':''}><span style="color:${r.accent}">${r.symbol} ${esc(r.subtitle)}</span><b>${esc(r.name)}</b><small>${esc(r.desc)}</small><small>${current?'VOCÊ ESTÁ AQUI':unlocked?`Viajar · ${r.cost} Âmbar`:`Rota selada · ${r.cost} Âmbar (decifre as ruínas)`}</small></button>`}).join('');$('regionGrid').querySelectorAll('[data-region]').forEach(b=>b.onclick=()=>travel(b.dataset.region))}
function travel(id){const r=regions.find(x=>x.id===id);if(!r||id===state.region)return;if(id==='abismo'&&!state.flags.ruins){toast('Decifre as ruínas para abrir a rota do Abismo.');return}if(r.cost>state.gold){toast(`Você precisa de ${r.cost} Âmbar para a viagem.`);return}state.gold-=r.cost;state.region=id;state.x=700;state.y=620;spawnedRegion='';ensureWorld();state.day++;state.time=(state.time+145)%1440;log(`Você chegou a ${r.name}.`,r.desc);setPanel('world');renderHUD();save()}

