if(ability.kind==='guard'){
  ally.guard=(ally.guard||0)+2+Math.floor(ally.level/2);
  battle.message=`${ally.name} bloqueou a ação e fortaleceu a guarda.`;
  battle.ally.hp=Math.min(ally.maxHp,ally.hp+Math.ceil(ally.maxHp*.08));
  renderBattle();
}else{
  const crit=Math.random() < 0.15;
  const baseDamage=Math.max(1,Math.round((ability.power + ally.level*2) * (crit?1.5:1)));
  enemy.hp=Math.max(0,enemy.hp-baseDamage);
  battle.message=crit?`${ally.name} executou ${ability.label} com precisão! ${baseDamage} de dano.`:`${ally.name} usou ${ability.label} e causou ${baseDamage} de dano.`;
  if(active) active.hp=clamp(ally.hp,0,active.maxHp);
  if(enemy.hp<=0){
    finishBattle(true);
    return;
  }
  const enemyMove=getEnemyMove(enemy);
  const guardDefense=ally.guard||0;
  const taken=Math.max(1,Math.round(enemyMove.power + enemy.level*2 - guardDefense));
  ally.hp=Math.max(0,ally.hp-taken);
  ally.guard=0;
  battle.message += ` ${species[enemy.species].name} respondeu com ${enemyMove.label}, causando ${taken} de dano.`;
  if(active){active.hp=clamp(ally.hp,0,active.maxHp);}
  if(ally.hp<=0){
    battle.ally.hp=0;
    finishBattle(false);
    return;
  }
  battle.enemySource.hp=clamp(enemy.hp,0,battle.enemySource.maxHp);
  battle.ally.hp=clamp(ally.hp,0,ally.maxHp);
  renderBattle();
  renderHUD();
}

