@media(max-width:480px){.game-stage{height:58vh;min-height:410px}.right-rail{grid-template-columns:1fr}.quest-mini-card{display:none}.story-feed{max-height:190px}.creature-grid,.codex-grid,.quest-grid,.inventory-grid{grid-template-columns:1fr}.objective{max-width:190px}.objective b{line-height:1.4}.weather-chip{max-width:112px;text-overflow:ellipsis;overflow:hidden;white-space:nowrap}.region-card{min-height:125px}.subview-header h1{font-size:30px}.codex-toolbar{gap:8px}.codex-toolbar input{width:145px}.panel-toolbar{gap:8px}.small-button{font-size:8px}}

/* Turn-based battle overlay and dimensional anime-inspired canvas finish. */
[hidden]{display:none!important}
.game-stage{isolation:isolate;background:#111b18;perspective:900px}
.game-stage::after{content:"";position:absolute;inset:0;pointer-events:none;z-index:1;background:linear-gradient(180deg,rgba(8,13,16,.12),transparent 25%,transparent 72%,rgba(5,9,8,.35));box-shadow:inset 0 0 100px #05090770}
#gameCanvas{filter:saturate(1.13) contrast(1.04);transform:translateZ(0)}
.battle-hud{position:absolute;z-index:4;right:clamp(16px,3vw,42px);bottom:18px;width:min(610px,calc(100% - 360px));padding:14px 16px 13px;border:1px solid #d5bd806b;border-radius:12px;background:linear-gradient(135deg,#17211fee,#101713f5);box-shadow:0 12px 40px #0009,inset 0 1px #fff2;backdrop-filter:blur(12px);animation:battle-enter .22s ease-out}
.battle-status{display:grid;grid-template-columns:minmax(105px,1fr) minmax(130px,1.15fr) minmax(105px,1fr);align-items:center;gap:14px}
.battle-status>div:not(.battle-message){display:grid;grid-template-columns:1fr auto;gap:5px 8px;align-items:center}
.battle-status small{grid-column:1/-1;color:#c5b27d;font-size:8px;letter-spacing:1.25px}
.battle-status b{font-size:12px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.battle-status span{color:#c6d0c8;font-size:10px;font-variant-numeric:tabular-nums}
